208	  /**
209	   * Connect to db
210	   * @returns {boolean}
211	   */
212	  async connect() {
213	    Logger.info(`[Database] Initializing db at "${this.dbPath}"`)
214	
215	    let logging = false
216	    let benchmark = false
217	    if (process.env.QUERY_LOGGING === 'log') {
218	      // Setting QUERY_LOGGING=log will log all Sequelize queries before they run
219	      Logger.info(`[Database] Query logging enabled`)
220	      logging = (query) => Logger.debug(`Running the following query:\n ${query}`)
221	    } else if (process.env.QUERY_LOGGING === 'benchmark') {
222	      // Setting QUERY_LOGGING=benchmark will log all Sequelize queries and their execution times, after they run
223	      Logger.info(`[Database] Query benchmarking enabled"`)
224	      logging = (query, time) => Logger.debug(`Ran the following query in ${time}ms:\n ${query}`)
225	      benchmark = true
226	    }
227	
228	    this.sequelize = new Sequelize({
229	      dialect: 'sqlite',
230	      storage: this.dbPath,
231	      logging: logging,
232	      benchmark: benchmark,
233	      transactionType: 'IMMEDIATE'
234	    })
235	
236	    // Helper function
237	    this.sequelize.uppercaseFirst = (str) => (str ? `${str[0].toUpperCase()}${str.substr(1)}` : '')
238	
239	    try {
240	      await this.sequelize.authenticate()
241	
242	      // Set SQLite pragmas from environment variables
243	      const allowedPragmas = [
244	        { name: 'mmap_size', env: 'SQLITE_MMAP_SIZE' },
245	        { name: 'cache_size', env: 'SQLITE_CACHE_SIZE' },
246	        { name: 'temp_store', env: 'SQLITE_TEMP_STORE' }
247	      ]
248	
249	      for (const pragma of allowedPragmas) {
250	        const value = process.env[pragma.env]
251	        if (value !== undefined) {
252	          try {
253	            Logger.info(`[Database] Running "PRAGMA ${pragma.name} = ${value}"`)
254	            await this.sequelize.query(`PRAGMA ${pragma.name} = ${value}`)
255	            const [result] = await this.sequelize.query(`PRAGMA ${pragma.name}`)
256	            Logger.debug(`[Database] "PRAGMA ${pragma.name}" query result:`, result)
257	          } catch (error) {
258	            Logger.error(`[Database] Failed to set SQLite pragma ${pragma.name}`, error)
259	          }
260	        }
261	      }
262	
263	      if (process.env.NUSQLITE3_PATH) {
264	        await this.loadExtension(process.env.NUSQLITE3_PATH)
265	        Logger.info(`[Database] Db supports unaccent and unicode foldings`)
266	        this.supportsUnaccent = true
267	        this.supportsUnicodeFoldings = true
268	      }
269	      Logger.info(`[Database] Db connection was successful`)
270	      return true
271	    } catch (error) {
272	      Logger.error(`[Database] Failed to connect to db`, error)
273	      return false
274	    }
275	  }
