280	  async loadExtension(extension) {
281	    // This is a hack to get the db connection for loading extensions.
282	    // The proper way would be to use the 'afterConnect' hook, but that hook is never called for sqlite due to a bug in sequelize.
283	    // See https://github.com/sequelize/sequelize/issues/12487
284	    // This is not a public API and may break in the future.
285	    const db = await this.sequelize.dialect.connectionManager.getConnection()
286	    if (typeof db?.loadExtension !== 'function') throw new Error('Failed to get db connection for loading extensions')
287	
288	    Logger.info(`[Database] Loading extension ${extension}`)
289	    await new Promise((resolve, reject) => {
290	      db.loadExtension(extension, (err) => {
291	        if (err) {
292	          Logger.error(`[Database] Failed to load extension ${extension}`, err)
293	          reject(err)
294	          return
295	        }
296	        Logger.info(`[Database] Successfully loaded extension ${extension}`)
297	        resolve()
298	      })
299	    })
300	  }
