855	  async addTriggerIfNotExists(sourceTable, sourceColumn, sourceIdColumn, targetTable, targetColumn, targetIdColumn) {
856	    const action = `update_${targetTable}_${targetColumn}`
857	    const fromSource = sourceTable === 'books' ? '' : `_from_${sourceTable}_${sourceColumn}`
858	    const triggerName = this.convertToSnakeCase(`${action}${fromSource}`)
859	
860	    const [[{ count }]] = await this.sequelize.query(`SELECT COUNT(*) as count FROM sqlite_master WHERE type='trigger' AND name='${triggerName}'`)
861	    if (count > 0) return // Trigger already exists
862	
863	    Logger.info(`[Database] Adding trigger ${triggerName}`)
864	
865	    await this.sequelize.query(`
866	      CREATE TRIGGER ${triggerName}
867	        AFTER UPDATE OF ${sourceColumn} ON ${sourceTable}
868	        FOR EACH ROW
869	        BEGIN
870	          UPDATE ${targetTable}
871	            SET ${targetColumn} = NEW.${sourceColumn}
872	          WHERE ${targetTable}.${targetIdColumn} = NEW.${sourceIdColumn};
873	        END;
874	    `)
