949	  TextSearchQuery = class {
950	    constructor(sequelize, supportsUnaccent, query) {
951	      this.sequelize = sequelize
952	      this.supportsUnaccent = supportsUnaccent
953	      this.query = query
954	      this.hasAccents = false
955	    }
956	
957	    /**
958	     * Returns a normalized (accents-removed) expression for the specified value.
959	     *
960	     * @param {string} value
961	     * @returns {string}
962	     */
963	    normalize(value) {
964	      return `unaccent(${value})`
965	    }
966	
967	    /**
968	     * Initialize the text query.
969	     *
970	     */
971	    async init() {
972	      if (!this.supportsUnaccent) return
973	      const escapedQuery = this.sequelize.escape(this.query)
974	      const normalizedQueryExpression = this.normalize(escapedQuery)
975	      const normalizedQueryResult = await this.sequelize.query(`SELECT ${normalizedQueryExpression} as normalized_query`)
976	      const normalizedQuery = normalizedQueryResult[0][0].normalized_query
977	      this.hasAccents = escapedQuery !== this.sequelize.escape(normalizedQuery)
978	    }
979	
980	    /**
981	     * Get match expression for the specified column.
982	     * If the query contains accents, match against the column as-is (case-insensitive exact match).
983	     * otherwise match against a normalized column (case-insensitive match with accents removed).
984	     *
985	     * @param {string} column
986	     * @returns {string}
987	     */
988	    matchExpression(column) {
989	      const pattern = this.sequelize.escape(`%${this.query}%`)
990	      if (!this.supportsUnaccent) return `${column} LIKE ${pattern}`
991	      const normalizedColumn = this.hasAccents ? column : this.normalize(column)
992	      return `${normalizedColumn} LIKE ${pattern}`
993	    }
994	  }
995	}
