// Usage: node countcasts.js <repoRoot> [files...]  (default: all .ts under server/ except libs and .d.ts)
// Counts `as` (excluding `as const`), `as unknown as` (counted once, not in `as`), non-null `!`,
// target types, and cast(x) tag comments.
const path = require('path')
const fs = require('fs')
const root = process.argv[2]
const ts = require(path.join(root, 'node_modules/typescript'))
let files = process.argv.slice(3)
if (!files.length) {
  const walk = (d) =>
    fs.readdirSync(d, { withFileTypes: true }).flatMap((e) => {
      const p = path.join(d, e.name)
      if (e.isDirectory()) return e.name === 'libs' ? [] : walk(p)
      return p.endsWith('.ts') && !p.endsWith('.d.ts') ? [p] : []
    })
  files = walk(path.join(root, 'server'))
  if (fs.existsSync(path.join(root, 'index.ts'))) files.push(path.join(root, 'index.ts'))
}
const tot = { as: 0, auu: 0, nn: 0 }
const byTarget = {}
const tags = {}
const perFile = {}
for (const f of files) {
  const src = fs.readFileSync(f, 'utf8')
  const sf = ts.createSourceFile(f, src, ts.ScriptTarget.ES2022, true)
  const pf = (perFile[path.relative(root, f)] = { as: 0, auu: 0, nn: 0 })
  const visit = (n) => {
    if (ts.isAsExpression(n)) {
      const t = n.type.getText(sf)
      if (t !== 'const') {
        const inner = n.expression
        const isOuterOfDouble = ts.isAsExpression(inner) && inner.type.kind === ts.SyntaxKind.UnknownKeyword
        const isInnerOfDouble = n.type.kind === ts.SyntaxKind.UnknownKeyword && ts.isAsExpression(n.parent) && n.parent.expression === n
        if (isOuterOfDouble) {
          tot.auu++, pf.auu++
          byTarget[t] = (byTarget[t] || 0) + 1
        } else if (!isInnerOfDouble) {
          tot.as++, pf.as++
          byTarget[t] = (byTarget[t] || 0) + 1
        }
      }
    }
    if (n.kind === ts.SyntaxKind.NonNullExpression) tot.nn++, pf.nn++
    ts.forEachChild(n, visit)
  }
  visit(sf)
  for (const m of src.matchAll(/cast\(([a-e])\)/g)) tags[m[1]] = (tags[m[1]] || 0) + 1
}
console.log('files', files.length, 'as', tot.as, 'as unknown as', tot.auu, '!', tot.nn)
console.log('tag comments', JSON.stringify(tags))
if (process.env.DETAIL) {
  console.log('per file', JSON.stringify(perFile, null, 1))
  console.log('by target', JSON.stringify(Object.entries(byTarget).sort((a, b) => b[1] - a[1]), null, 0))
}

