// Usage: node normjs.js <repoRoot> <dirA> <dirB> <outDir>
// Prints every .js file of dirA and dirB (relative paths) with the TypeScript printer after removing comments,
// parenthesized expressions and quote style, writes them to outDir/a and outDir/b, and lists differing files.
const path = require('path')
const fs = require('fs')
const [root, dirA, dirB, outDir] = process.argv.slice(2)
const ts = require(path.join(root, 'node_modules/typescript'))
const walk = (d, base = d) =>
  fs.existsSync(d)
    ? fs.readdirSync(d, { withFileTypes: true }).flatMap((e) => {
        const p = path.join(d, e.name)
        if (e.isDirectory()) return walk(p, base)
        return p.endsWith('.js') ? [path.relative(base, p)] : []
      })
    : []
const norm = (file) => {
  const src = fs.readFileSync(file, 'utf8')
  const sf = ts.createSourceFile(file, src, ts.ScriptTarget.ES2022, false, ts.ScriptKind.JS)
  const tr = (ctx) => {
    const v = (n) => {
      if (ts.isParenthesizedExpression(n)) return ts.visitNode(n.expression, v)
      if (ts.isStringLiteral(n)) return ts.factory.createStringLiteral(n.text)
      return ts.visitEachChild(n, v, ctx)
    }
    return (s) => ts.visitNode(s, v)
  }
  const out = ts.transform(sf, [tr]).transformed[0]
  return ts.createPrinter({ removeComments: true }).printFile(out)
}
const a = new Set(walk(dirA).filter((f) => !f.startsWith('server/libs/')))
const b = new Set(walk(dirB).filter((f) => !f.startsWith('server/libs/')))
const diffs = []
for (const f of new Set([...a, ...b])) {
  if (!a.has(f)) { diffs.push('only in B: ' + f); continue }
  if (!b.has(f)) { diffs.push('only in A: ' + f); continue }
  const na = norm(path.join(dirA, f))
  const nb = norm(path.join(dirB, f))
  if (na !== nb) {
    diffs.push('differs: ' + f)
    for (const [d, t] of [['a', na], ['b', nb]]) {
      const p = path.join(outDir, d, f)
      fs.mkdirSync(path.dirname(p), { recursive: true })
      fs.writeFileSync(p, t)
    }
  }
}
console.log(diffs.sort().join('\n') || 'no differences')

