// Server smoke test. Usage: node smoke.js <repoRoot> <label> [--watcher]
// Creates a fresh directory under the scratchpad (mkdtemp), never deletes anything.
const path = require('path')
const fs = require('fs')
const { spawn, execFileSync } = require('child_process')
const [repo, label] = process.argv.slice(2)
const withWatcher = process.argv.includes('--watcher')
const scratch = __dirname
const base = fs.mkdtempSync(path.join(scratch, `smoke-${label}-`))
const cfg = path.join(base, 'config')
const meta = path.join(base, 'metadata')
const lib = path.join(base, 'library')
const port = 13378
const url = `http://127.0.0.1:${port}`
const ffmpeg = path.join(repo, 'ffmpeg')
const sleep = (ms) => new Promise((r) => setTimeout(r, ms))

function makeAudio(file, title, artist, album) {
  fs.mkdirSync(path.dirname(file), { recursive: true })
  execFileSync(ffmpeg, ['-loglevel', 'error', '-f', 'lavfi', '-i', 'sine=frequency=440:duration=3', '-metadata', `title=${title}`, '-metadata', `artist=${artist}`, '-metadata', `album=${album}`, '-q:a', '9', file])
}

async function req(method, p, { token, body } = {}) {
  const headers = {}
  if (token) headers.Authorization = `Bearer ${token}`
  if (body) headers['Content-Type'] = 'application/json'
  const res = await fetch(url + p, { method, headers, body: body ? JSON.stringify(body) : undefined })
  const text = await res.text()
  let json = null
  try { json = JSON.parse(text) } catch {}
  return { status: res.status, json, text }
}

;(async () => {
  console.log('base dir', base)
  makeAudio(path.join(lib, 'Author One', 'Book One', '01.mp3'), 'Chapter 1', 'Author One', 'Book One')
  makeAudio(path.join(lib, 'Author One', 'Book One', '02.mp3'), 'Chapter 2', 'Author One', 'Book One')
  makeAudio(path.join(lib, 'Author Two', 'Book Two', 'book.mp3'), 'Book Two', 'Author Two', 'Book Two')

  const out = fs.openSync(path.join(base, 'server.log'), 'w')
  const env = { ...process.env, SKIP_BINARIES_CHECK: '1', FFMPEG_PATH: ffmpeg, FFPROBE_PATH: path.join(repo, 'ffprobe') }
  delete env.NODE_ENV
  const proc = spawn('node', ['dist-server/index.js', '--config', cfg, '--metadata', meta, '--port', String(port), '--host', '127.0.0.1'], { cwd: repo, env, stdio: ['ignore', out, out] })
  let up = false
  for (let i = 0; i < 60 && !up; i++) {
    await sleep(500)
    try { up = (await fetch(url + '/healthcheck')).status === 200 } catch {}
  }
  console.log('server up:', up)
  const r = {}
  r.status = await req('GET', '/status')
  console.log('GET /status', r.status.status, JSON.stringify({ isInit: r.status.json?.isInit, serverVersion: r.status.json?.serverVersion, authMethods: r.status.json?.authMethods, hasConfigPath: !!r.status.json?.ConfigPath }))
  r.init = await req('POST', '/init', { body: { newRoot: { username: 'root', password: 'secretpw' } } })
  console.log('POST /init', r.init.status, r.init.text)
  r.status2 = await req('GET', '/status')
  console.log('GET /status (after init)', r.status2.status, 'isInit', r.status2.json?.isInit)
  r.login = await req('POST', '/login', { body: { username: 'root', password: 'secretpw' } })
  const token = r.login.json?.user?.accessToken
  console.log('POST /login', r.login.status, 'user', r.login.json?.user?.username, 'type', r.login.json?.user?.type, 'accessToken', !!token, 'refreshToken in body', r.login.json?.user?.refreshToken ?? null, 'Source', r.login.json?.Source)
  r.bad = await req('POST', '/login', { body: { username: 'root', password: 'wrong' } })
  console.log('POST /login (wrong password)', r.bad.status, r.bad.text)
  for (const p of ['/api/libraries', '/api/me', '/api/users']) {
    const x = await req('GET', p, { token })
    const summary = p === '/api/libraries' ? `libraries=${x.json?.libraries?.length}` : p === '/api/me' ? `username=${x.json?.username}` : `users=${x.json?.users?.length}`
    console.log('GET', p, x.status, summary)
  }
  const created = await req('POST', '/api/libraries', { token, body: { name: 'Smoke Books', folders: [{ fullPath: lib }], mediaType: 'book' } })
  const libraryId = created.json?.id
  console.log('POST /api/libraries', created.status, 'id', libraryId, 'folders', created.json?.folders?.length)
  const scan = await req('POST', `/api/libraries/${libraryId}/scan`, { token })
  console.log('POST /api/libraries/<id>/scan', scan.status)
  let items = null
  for (let i = 0; i < 40; i++) {
    await sleep(500)
    items = await req('GET', `/api/libraries/${libraryId}/items`, { token })
    if (items.json?.total >= 2) break
  }
  const titles = (it) => (it.json?.results || []).map((li) => `${li.media?.metadata?.title} [${li.media?.metadata?.authorName}] tracks=${li.media?.numTracks ?? li.media?.numAudioFiles}`)
  console.log('GET /api/libraries/<id>/items', items.status, 'total', items.json?.total, JSON.stringify(titles(items)))
  const libs = await req('GET', '/api/libraries', { token })
  console.log('GET /api/libraries', libs.status, 'libraries', libs.json?.libraries?.length)

  if (withWatcher) {
    // New folder with an audio file, written elsewhere first and then moved in (one add event per file)
    const tmpFile = path.join(base, 'incoming.mp3')
    makeAudio(tmpFile, 'Book Three', 'Author Three', 'Book Three')
    fs.mkdirSync(path.join(lib, 'Author Three', 'Book Three'), { recursive: true })
    fs.renameSync(tmpFile, path.join(lib, 'Author Three', 'Book Three', 'book3.mp3'))
    console.log('watcher: added', path.join('Author Three', 'Book Three', 'book3.mp3'))
    let w = null
    for (let i = 0; i < 60; i++) {
      await sleep(1000)
      w = await req('GET', `/api/libraries/${libraryId}/items`, { token })
      if (w.json?.total >= 3) break
    }
    console.log('watcher: GET /api/libraries/<id>/items', w.status, 'total', w.json?.total, JSON.stringify(titles(w)))

    // Socket: raw Engine.IO v4 / Socket.IO v5 over Node's built-in WebSocket (socket.io-client is not installed)
    const events = await new Promise((resolve) => {
      const got = []
      const ws = new WebSocket(`ws://127.0.0.1:${port}/socket.io/?EIO=4&transport=websocket`)
      const done = () => { try { ws.close() } catch {} ; resolve(got) }
      const timer = setTimeout(done, 8000)
      ws.onmessage = (m) => {
        const d = String(m.data)
        got.push(d.length > 300 ? d.slice(0, 300) + '...' : d)
        if (d.startsWith('0')) ws.send('40') // socket.io connect to namespace /
        else if (d.startsWith('40')) ws.send(`42${JSON.stringify(['auth', token])}`)
        else if (d === '2') ws.send('3') // ping -> pong
        else if (d.startsWith('42["init"')) { clearTimeout(timer); done() }
      }
      ws.onerror = (e) => { got.push('error ' + e.message); clearTimeout(timer); done() }
    })
    console.log('socket frames:', JSON.stringify(events, null, 1))
  }

  proc.kill('SIGINT')
  await new Promise((r) => proc.on('exit', r))
  await sleep(300)
  const log = fs.readFileSync(path.join(base, 'server.log'), 'utf8')
  const bad = log.split('\n').filter((l) => / (ERROR|WARN|FATAL):/.test(l))
  console.log(`log lines with ERROR/WARN/FATAL (${bad.length}):\n` + bad.join('\n'))
  const logsDir = path.join(meta, 'logs')
  const listDir = (d) => (fs.existsSync(d) ? fs.readdirSync(d, { withFileTypes: true }).flatMap((e) => (e.isDirectory() ? listDir(path.join(d, e.name)) : [path.relative(meta, path.join(d, e.name)) + ` (${fs.statSync(path.join(d, e.name)).size} bytes)`])) : ['(missing)'])
  console.log('metadata/logs files:', JSON.stringify(listDir(logsDir)))
  const daily = listDir(path.join(logsDir, 'daily'))
  console.log('server log file:', path.join(base, 'server.log'))
})()

